class DoubtHint {
  const DoubtHint({
    required this.level,
    required this.text,
    required this.source,
  });

  factory DoubtHint.fromJson(Map<String, dynamic> json) => DoubtHint(
    level: json['level'] as int,
    text: json['text'] as String,
    source: json['source'] as String,
  );

  final int level;
  final String text;

  /// `llm` (generated by the AI) or `reference` (standard hint from the question's own solution).
  final String source;

  bool get isAi => source == 'llm';
}

class Doubt {
  const Doubt({
    required this.id,
    required this.status,
    required this.hintsUsed,
    required this.maxHints,
    required this.hints,
    this.message,
  });

  factory Doubt.fromJson(Map<String, dynamic> json) => Doubt(
    id: json['id'] as String,
    status: json['status'] as String,
    message: json['message'] as String?,
    hintsUsed: json['hintsUsed'] as int,
    maxHints: json['maxHints'] as int,
    hints: (json['hints'] as List<dynamic>)
        .map((h) => DoubtHint.fromJson(h as Map<String, dynamic>))
        .toList(),
  );

  final String id;

  /// `AI_HINTS`, `WAITING_TEACHER` or `ANSWERED`.
  final String status;
  final String? message;
  final int hintsUsed;
  final int maxHints;
  final List<DoubtHint> hints;

  bool get hasMoreHints => hintsUsed < maxHints;
}

/// The hint just delivered, with whether more are available.
class HintResult {
  const HintResult({
    required this.hint,
    required this.hintsUsed,
    required this.hasMore,
    this.notice,
  });

  factory HintResult.fromJson(Map<String, dynamic> json) => HintResult(
    hint: DoubtHint.fromJson(json),
    hintsUsed: json['hintsUsed'] as int,
    hasMore: json['hasMore'] as bool,
    notice: json['notice'] as String?,
  );

  final DoubtHint hint;
  final int hintsUsed;
  final bool hasMore;

  /// Set when the AI was skipped on purpose (usage limit).
  final String? notice;
}
